/**
 * A threshold range
 */
export interface ColoredRange {
  /** Range starting point */
  from: number;
  /** Range ending point */
  to: number;
  /** The color to use in this range  */
  color?: string;
}

export function isColoredRange(colorRange: object): colorRange is ColoredRange {
  return (
    Object.keys(colorRange).includes('to') &&
    Object.keys(colorRange).includes('from')
  );
}
